        n = len(nums)
        mx = mn = 0
        for j in range(indexDifference, n):
            k = j - indexDifference
            if nums[k] > nums[mx]:
                mx = k
            if nums[k] < nums[mn]:
                mn = k
            if nums[mx] - nums[j] >= valueDifference:
                return [mx, j]
            if nums[j] - nums[mn] >= valueDifference:
                return [mn, j]
        return [-1, -1]

